import{_ as t,o as r,c as a,a5 as o}from"./chunks/framework.CslsFoWx.js";const s="/VendoraSystem-docs/captures/2026-11-10-corrections-captures/01-ios-hors-ligne-22-jours-barre.webp",n="/VendoraSystem-docs/captures/2026-11-10-corrections-captures/02-ios-feuille-synchronisation-22-jours.webp",i="/VendoraSystem-docs/captures/2026-11-10-corrections-captures/03-android-hors-ligne-22-jours-barre.webp",d="/VendoraSystem-docs/captures/2026-11-10-corrections-captures/04-android-feuille-synchronisation-22-jours.webp",c="/VendoraSystem-docs/captures/2026-11-10-corrections-captures/04a-android-feuille-avant-correctif-sans-hors-ligne.webp",l="/VendoraSystem-docs/captures/2026-11-10-corrections-captures/05-android-stepper-arabe-moins-a-gauche.webp",u="/VendoraSystem-docs/captures/2026-11-10-corrections-captures/08-android-telephone-reappaire-epicerie-seule.webp",p="/VendoraSystem-docs/captures/2026-11-10-corrections-captures/06-android-grille-vignette-serree-avant.webp",h="/VendoraSystem-docs/captures/2026-11-10-corrections-captures/07-android-grille-apres-et-produits-epicerie.webp",q=JSON.parse('{"title":"Corrections trouvées pendant les captures du 10/11/2026","description":"","frontmatter":{},"headers":[],"relativePath":"preuves/2026-11-10-corrections-captures.md","filePath":"generated/preuves/2026-11-10-corrections-captures.md","lastUpdated":null}'),m={name:"preuves/2026-11-10-corrections-captures.md"};function g(b,e,v,y,f,S){return r(),a("div",null,[...e[0]||(e[0]=[o('<h1 id="corrections-trouvees-pendant-les-captures-du-10-11-2026" tabindex="-1">Corrections trouvées pendant les captures du 10/11/2026 <a class="header-anchor" href="#corrections-trouvees-pendant-les-captures-du-10-11-2026" aria-label="Permalink to &quot;Corrections trouvées pendant les captures du 10/11/2026&quot;">​</a></h1><p class="muted">Dossier <code>docs/captures/2026-11-10-corrections-captures</code> · 0 image(s) · 0 trace(s)</p><div><p>Deux défauts relevés pendant les captures du 10/11, corrigés avec tests et parité iOS / Android.</p><h2 id="_1-«-jamais-synchronise-»-apres-un-lancement-hors-ligne" tabindex="-1">1. « Jamais synchronisé » après un lancement hors ligne <a class="header-anchor" href="#_1-«-jamais-synchronise-»-apres-un-lancement-hors-ligne" aria-label="Permalink to &quot;1. « Jamais synchronisé » après un lancement hors ligne&quot;">​</a></h2><p><strong>Cause</strong> : l&#39;état de synchro des écrans de vente (<code>CatalogViewModel</code> iOS et Android) démarrait à <code>offline(lastSyncMillis: nil)</code> et ne connaissait que les pulls de la session en cours. Au lancement hors ligne, le premier pull échouait et gardait ce <code>nil</code> : la feuille Synchronisation affichait « Jamais synchronisé » alors que <code>sync_state.last_pull_at</code> (lu par les seuils RG-SYNC-21 et le cache d&#39;auth RG-AUTH-23) datait de 22 jours. De plus, le libellé ne donnait que l&#39;heure (« Dernière synchronisation à 14:05 »), trompeur pour un échange vieux de plusieurs jours.</p><p><strong>Correction</strong> (code partagé + les deux apps) :</p><ul><li><code>shared</code> : <code>SyncStateRepository.lastPullAt()</code> (même colonne que RG-SYNC-21) et <code>LastSyncLabel.detail()</code>, libellé commun : heure si moins de 24 h, « Dernière synchronisation il y a N jours » au-delà (même décompte en jours entiers que <code>SyncHealth.daysWithoutSync</code>), « Jamais synchronisé » sans pull réussi ; texte <code>lastSyncDaysAgo</code> en fr / en / ar.</li><li>iOS et Android : le dernier pull persistant est relu au démarrage (caisse et téléphone de salle) et gardé si le pull échoue ; la feuille Synchronisation passe par <code>LastSyncLabel</code>.</li></ul><p><strong>Vraie stack</strong> : serveur de dev <code>localhost:8080</code>, commerce de démo FICTIF « Le Petit Bistrot (démo) », simulateur iPhone 16 (iOS 26.2) <strong>dédié</strong>, appairé comme caisse (« Caisse iPhone (démo) »), app construite depuis cette branche. Après un premier pull réussi : app arrêtée, <code>sync_state.last_pull_at</code> reculé de 22 jours dans la base du simulateur, relance avec l&#39;argument <code>-server.url http://localhost:9</code> (serveur injoignable = hors ligne), connexion « Sophie (manager) » (PIN manager en mode dégradé au-delà de 72 h). Gestes par le pilote XCUITest.</p><table tabindex="0"><thead><tr><th>Capture</th><th>Ce qu&#39;elle prouve</th></tr></thead><tbody><tr><td><img src="'+s+'" alt=""></td><td>Lancement hors ligne : pastille <strong>Attention</strong> (1) et bandeau critique RG-SYNC-21 « 22 jours sans synchronisation » (2), lus de <code>last_pull_at</code>.</td></tr><tr><td><img src="'+n+'" alt=""></td><td>Feuille Synchronisation : <strong>« Hors ligne — Dernière synchronisation il y a 22 jours »</strong> (1) au lieu de « Jamais synchronisé » ; cohérent avec le bandeau critique juste dessous.</td></tr></tbody></table><p>Avant : « Hors ligne — Jamais synchronisé » dans la même feuille (captures du 10/11 de l&#39;intégrateur).</p><h3 id="android-telephone-emulator-5556-10-11-2026" tabindex="-1">Android (téléphone <code>emulator-5556</code>, 10/11/2026) <a class="header-anchor" href="#android-telephone-emulator-5556-10-11-2026" aria-label="Permalink to &quot;Android (téléphone `emulator-5556`, 10/11/2026)&quot;">​</a></h3><p>Téléphone Android (AVD Medium_Phone_API_36.1), app de main, appairé comme caisse « Caisse téléphone (démo) » du commerce fictif « Épicerie Lumière (démo) » après un premier pull réussi. App arrêtée (<code>am force-stop</code>), <code>pos.db</code> lue par <code>run-as</code>, <code>sync_state.last_pull_at</code> reculé de 22 jours (<code>sqlite3</code> sur le Mac), base réécrite, <strong>mode avion</strong>, relance ; Nora (caisse) reste connectée (session d&#39;utilisateur conservée).</p><table tabindex="0"><thead><tr><th>Capture</th><th>Ce qu&#39;elle prouve</th></tr></thead><tbody><tr><td><img src="'+i+'" alt=""></td><td>Lancement hors ligne : pastille <strong>Attention</strong> (1) et bandeaux « Dernière synchronisation il y a plus de 72 h — PIN manager en mode dégradé » et « Synchronisation critique : 22 jours sans synchronisation… » (2), lus de <code>last_pull_at</code>.</td></tr><tr><td><img src="'+d+'" alt=""></td><td>Feuille Synchronisation : <strong>« Hors ligne — Dernière synchronisation il y a 22 jours »</strong> (1), cohérent avec le bandeau critique juste dessous.</td></tr><tr><td><img src="'+c+'" alt=""></td><td><strong>Avant le correctif trouvé pendant cette capture</strong> : « Dernière synchronisation il y a 22 jours · temps réel magasin » (1) — le dernier pull était bien relu, mais sans « Hors ligne — » (l&#39;iOS l&#39;affiche) et avec le suffixe du hub local même en mode avion ; pendant un pull, la ligne disait « Jamais synchronisé » au lieu de « Envoi… ».</td></tr></tbody></table><p><strong>Correctif</strong> (commit <code>androidApp</code>) : <code>syncDetailLine</code> (<code>CashierMenu.kt</code>) reprend les textes de l&#39;iOS (<code>SaleView.lignesSynchro</code>) : « Envoi… » pendant un pull, « Hors ligne — » + <code>LastSyncLabel</code> hors ligne (sans suffixe du hub), heure + suffixe « temps réel magasin » en ligne. Test <code>SyncDetailLineTest</code> (2 cas, fr et en).</p><h2 id="_2-selecteur-de-quantite-«-n-−-»-en-arabe-sur-android" tabindex="-1">2. Sélecteur de quantité « + n − » en arabe sur Android <a class="header-anchor" href="#_2-selecteur-de-quantite-«-n-−-»-en-arabe-sur-android" aria-label="Permalink to &quot;2. Sélecteur de quantité « + n − » en arabe sur Android&quot;">​</a></h2><p><strong>Cause</strong> : le composant Compose <code>Stepper</code> (et trois « − n + » écrits à la main) suivait la direction RTL et inversait la rangée, alors qu&#39;iOS fige <code>PosStepper</code> en <code>leftToRight</code> (décision « UX restes » : ordre d&#39;une droite numérique, chiffres 0-9, RG-THEME-12).</p><p><strong>Correction</strong> : nouveau <code>NumericStepperRow</code> (disposition LTR figée, étiquettes d&#39;accessibilité inchangées) utilisé par <code>Stepper</code> — donc parcours formule, ligne de panier, borne (fiche et panier), couverts, brouillon de commande, partage d&#39;addition — et par les « − n + » du retour (ligne et formule retournée) et de la réception de transfert. Garde-fou <code>StepperRtlTest</code> (sources).</p><h3 id="android-tablette-emulator-5554-10-11-2026" tabindex="-1">Android (tablette <code>emulator-5554</code>, 10/11/2026) <a class="header-anchor" href="#android-tablette-emulator-5554-10-11-2026" aria-label="Permalink to &quot;Android (tablette `emulator-5554`, 10/11/2026)&quot;">​</a></h3><p>App de main réinstallée sur la tablette (session n° 1 conservée), langue <strong>arabe</strong> par <code>localeOverride</code>, Vente directe › Formule midi.</p><table tabindex="0"><thead><tr><th>Capture</th><th>Ce qu&#39;elle prouve</th></tr></thead><tbody><tr><td><img src="'+l+'" alt=""></td><td>Parcours formule en arabe : la rangée « الكمية » (2) affiche <strong>− 1 +</strong> (moins à gauche, plus à droite) (1), comme l&#39;iOS. Avant (app du 10/11 à 01:43, capture <code>2026-11-09-formules-retour/android-03-…</code>) : « + 1 − ».</td></tr></tbody></table><h2 id="_3-defauts-trouves-pendant-les-captures-android-du-10-11-et-corriges" tabindex="-1">3. Défauts trouvés pendant les captures Android du 10/11 et corrigés <a class="header-anchor" href="#_3-defauts-trouves-pendant-les-captures-android-du-10-11-et-corriges" aria-label="Permalink to &quot;3. Défauts trouvés pendant les captures Android du 10/11 et corrigés&quot;">​</a></h2><h3 id="donnees-d-un-appairage-precedent-gardees-au-reappairage-shared-ios-android" tabindex="-1">Données d&#39;un appairage précédent gardées au réappairage (shared, iOS + Android) <a class="header-anchor" href="#donnees-d-un-appairage-precedent-gardees-au-reappairage-shared-ios-android" aria-label="Permalink to &quot;Données d&#39;un appairage précédent gardées au réappairage (shared, iOS + Android)&quot;">​</a></h3><p><strong>Constat</strong> : le téléphone, appairé à l&#39;épicerie fictive puis au commerce <code>tr0911</code> puis au Petit Bistrot, montrait au catalogue du Petit Bistrot « Beurre doux 250 g » (épicerie) et chaque produit du restaurant <strong>en double</strong> (76 produits, 3 plans de salle, ventes, alertes, cache d&#39;auth des anciens magasins — base relue par <code>run-as</code>). La tablette a le même symptôme (produits de l&#39;épicerie « Bananes (kg) », « Beurre doux 250 g », « Comté 18 mois »… au catalogue du restaurant, capture 07 (3)) : elle reste appairée au Petit Bistrot (session ouverte), son miroir ne sera nettoyé qu&#39;à un réappairage vers un autre magasin.</p><p><strong>Cause</strong> : <code>SyncStateRepository.initialize</code> remettait le curseur de pull à zéro quand le magasin change, mais ne vidait que l&#39;état de caisse (<code>resetPairingLocalState</code>) : le miroir (catalogue, plan de salle, ventes…) restait.</p><p><strong>Correction</strong> : <code>deleteStoreMirror</code> (<code>PairingReset.sq</code>) vide toutes les tables du miroir au changement de magasin quand rien de métier n&#39;attend d&#39;être envoyé (gardées : <code>sync_state</code>, <code>outbox_event</code>, <code>printer_config</code>, <code>pending_backfill</code>). Test <code>StoreMirrorResetTest</code> (4 cas, dont un garde-fou : toute nouvelle table doit être vidée ou gardée expressément).</p><table tabindex="0"><thead><tr><th>Capture</th><th>Ce qu&#39;elle prouve</th></tr></thead><tbody><tr><td><img src="'+u+'" alt=""></td><td>Après le correctif : téléphone réappairé à l&#39;épicerie, catalogue de l&#39;épicerie <strong>seul</strong> (1) (17 produits, aucun du restaurant) ; puis réappairé au Petit Bistrot en téléphone de Lucas : 30 produits, aucun de l&#39;épicerie, un seul plan de salle.</td></tr></tbody></table><h3 id="tuiles-de-resultats-vignette-qui-coupe-le-nom-androidapp" tabindex="-1">Tuiles de résultats : vignette qui coupe le nom (androidApp) <a class="header-anchor" href="#tuiles-de-resultats-vignette-qui-coupe-le-nom-androidapp" aria-label="Permalink to &quot;Tuiles de résultats : vignette qui coupe le nom (androidApp)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Avant</th><th>Après</th><th>Ce que montre la capture</th></tr></thead><tbody><tr><td><img src="'+p+'" alt=""></td><td><img src="'+h+'" alt=""></td><td>Tablette paysage, Vente directe sans écran de vente : 5 colonnes de ~116 dp. Avant : la vignette serrait le nom (« Burge / r du … » (1), « Form / ule … » (2)). Après : pas de vignette dans les tuiles de résultats, comme l&#39;iOS (<code>PosProductTile</code> sans <code>vignetteCompacte</code>) — noms entiers (1) (2). (3) : produits de l&#39;épicerie restés dans le miroir de la tablette (défaut ci-dessus). Test <code>ResultTilesNoThumbnailTest</code>.</td></tr></tbody></table><h3 id="feuille-synchronisation-android-sans-«-hors-ligne-—-»" tabindex="-1">Feuille Synchronisation Android sans « Hors ligne — » <a class="header-anchor" href="#feuille-synchronisation-android-sans-«-hors-ligne-—-»" aria-label="Permalink to &quot;Feuille Synchronisation Android sans « Hors ligne — »&quot;">​</a></h3><p>Voir section 1 (capture 04a / 04) ; test <code>SyncDetailLineTest</code>.</p><h3 id="ecran-cuisine-sur-telephone-«-chef-»-coupe" tabindex="-1">Écran cuisine sur téléphone : « Chef : … » coupé <a class="header-anchor" href="#ecran-cuisine-sur-telephone-«-chef-»-coupe" aria-label="Permalink to &quot;Écran cuisine sur téléphone : « Chef : … » coupé&quot;">​</a></h3><p>Voir <code>2026-11-09-role-a-chaud-seuil</code> (captures <code>android-13b</code> / <code>android-14</code>) ; test <code>KdsBarSubtitleTest</code>.</p><h2 id="tests" tabindex="-1">Tests <a class="header-anchor" href="#tests" aria-label="Permalink to &quot;Tests&quot;">​</a></h2><ul><li><code>:shared:jvmTest</code> 597 / 0 échec ; <code>:shared:iosSimulatorArm64Test</code> 583 / 0 échec (dont <code>LastSyncLabelTest</code> 5 cas, <code>CaisseStringsTest</code> étendu).</li><li><code>:androidApp:testDebugUnitTest</code> 321 / 0 échec (dont <code>CatalogViewModelTest</code> +2, <code>StepperRtlTest</code> 2).</li><li>iOS <code>xcodebuild test</code> (simulateur dédié) : 324 + 2 tests, 0 échec (dont <code>SynchroHorlogeRevocationTests.testLancementHorsLigne_dernierPullPersistantRelu_libelleEnJours</code>).</li><li>Centre d&#39;aide : <code>npm run build</code> vert, <code>coverage:strict</code> vert.</li><li>Après les correctifs de la section 3 (10/11, captures Android) : <code>:shared:jvmTest</code> 602 / 0 échec (dont <code>StoreMirrorResetTest</code> 4) ; <code>:shared:iosSimulatorArm64Test</code> 588, 1 échec non lié et intermittent (<code>UserSessionTest</code>, assertion « jamais de PIN » : la charge utile contenait « 1357 », le PIN du test — sans doute dans un identifiant aléatoire, non reproduit), vert à la relance ; <code>:androidApp:testDebugUnitTest</code> 326 / 0 échec avant <code>ResultTilesNoThumbnailTest</code> (1, vert).</li></ul></div>',3)])])}const A=t(m,[["render",g]]);export{q as __pageData,A as default};
